SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=1;
UPDATE project_planner_items SET planned_start_date=COALESCE(planned_start_date, DATE_SUB('2026-09-30', INTERVAL (200 - sort_order*4) DAY)), planned_end_date=COALESCE(planned_end_date, DATE_SUB('2026-09-30', INTERVAL (185 - sort_order*4) DAY)), assigned_to=COALESCE(assigned_to, '5c877a40-c982-5e88-88ef-92b0eade87e6'), status=IF(status='NOT_STARTED' AND sort_order<40,'COMPLETED',status), progress_pct=IF(status='COMPLETED',100,progress_pct) WHERE planner_id='a6feb5e3-6a5f-47be-87e6-0116b2b3e9e6';
